import { getElement } from '../../utils/functional';

class InsertCheckoutTerms {
  constructor() {
    this.setupEls = this.setupEls.bind(this);
    this.init = this.init.bind(this);
    this.setupEls();
    this.init();
  }

  setupEls() {
    this.els = {
      checkoutTermsEl: getElement('.js-Checkout_Terms'),
      stepFooterEl: getElement('.step__footer')
    };
  }

  init() {
    if (this.checkoutTermsHtml && this.els.stepFooterEl) {
      this.els.stepFooterEl.innerHTML = this.els.stepFooterEl.innerHTML + this.checkoutTermsHtml;
    }
  }

  get checkoutTermsHtml() {
    if (!this.els.checkoutTermsEl || !this.els.checkoutTermsEl.innerHTML.length) return null;
    return this.els.checkoutTermsEl.innerHTML;
  }

}

function insertCheckoutTerms() {
  return new InsertCheckoutTerms();
}

insertCheckoutTerms();